import{_ as a,o as t,c as o,a3 as i}from"./chunks/framework.B5WAEDB7.js";const m=JSON.parse('{"title":"2025 roadmap","description":"Planned Wheel.OS and Wheel.App features, tools and operational capabilities.","frontmatter":{"title":"2025 roadmap","description":"Planned Wheel.OS and Wheel.App features, tools and operational capabilities.","status":"Planned","content_type":"roadmap","keywords":["WheelOS","roadmap","Wheel.OS","Wheel.App","planned capability"]},"headers":[],"relativePath":"en/roadmap/2025.md","filePath":"en/roadmap/2025.md","lastUpdated":1794216847000}'),n={name:"en/roadmap/2025.md"};function r(l,e,s,d,p,c){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="autonomous-driving-system-release-roadmap" tabindex="-1">Autonomous-driving system release roadmap <a class="header-anchor" href="#autonomous-driving-system-release-roadmap" aria-label="Permalink to &quot;Autonomous-driving system release roadmap&quot;">​</a></h1><blockquote><p>This page describes planned objectives. It does not mean that every feature has shipped or completed real-vehicle validation.</p></blockquote><h2 id="wheel-os-release-plan" tabindex="-1">Wheel.OS release plan <a class="header-anchor" href="#wheel-os-release-plan" aria-label="Permalink to &quot;Wheel.OS release plan&quot;">​</a></h2><h3 id="version-12-31" tabindex="-1">Version 12.31 <a class="header-anchor" href="#version-12-31" aria-label="Permalink to &quot;Version 12.31&quot;">​</a></h3><h4 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h4><ul><li><strong>Core middleware:</strong> support core modules and improve stability.</li><li><strong>Common_msgs:</strong> provide standard message interfaces for efficient module communication.</li><li><strong>Sensor drivers:</strong> improve support and compatibility for multiple sensors.</li><li><strong>Vehicle chassis:</strong> enable chassis control and debugging with better adaptation.</li></ul><h4 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h4><ul><li><strong>Aconf:</strong> flexible configuration loading.</li><li><strong>Cviz:</strong> real-time visualization of key autonomous-driving data.</li><li><strong>DBC_tool:</strong> improve vehicle-chassis adaptation.</li><li><strong>Chassis debugging:</strong> support chassis diagnostics and performance tuning.</li></ul><h2 id="wheel-app-release-plan" tabindex="-1">Wheel.App release plan <a class="header-anchor" href="#wheel-app-release-plan" aria-label="Permalink to &quot;Wheel.App release plan&quot;">​</a></h2><h3 id="version-2-28" tabindex="-1">Version 2.28 <a class="header-anchor" href="#version-2-28" aria-label="Permalink to &quot;Version 2.28&quot;">​</a></h3><ul><li><strong>Features:</strong> basic localization, perception foundation, dynamic-object prediction, initial path planning and vehicle control.</li><li><strong>Tools:</strong> sensor calibration, sensor time synchronization, vehicle-dynamics calibration and CARLA bridge integration.</li></ul><h3 id="version-6-30" tabindex="-1">Version 6.30 <a class="header-anchor" href="#version-6-30" aria-label="Permalink to &quot;Version 6.30&quot;">​</a></h3><ul><li><strong>Middleware:</strong> runtime performance optimization.</li><li><strong>Hardware adaptation:</strong> Horizon J6 and NX5.</li><li><strong>Localization:</strong> indoor localization and multi-sensor fusion.</li><li><strong>Perception:</strong> performance improvements, semantic segmentation and a robust development process.</li><li><strong>Prediction:</strong> improved behavior prediction for dynamic environments.</li><li><strong>Planning:</strong> map-independent planning and path behavior trees.</li><li><strong>Control:</strong> continued vehicle-control optimization.</li><li><strong>Operations:</strong> functional-safety work, dispatch/status management and remote driving.</li><li><strong>Tools:</strong> vehicle-dynamics modeling.</li></ul><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Version</th><th>Features</th><th>Tools</th><th>Other modules</th></tr></thead><tbody><tr><td><strong>Wheel.OS 12.31</strong></td><td>Core middleware, Common_msgs, drivers, vehicles</td><td>Aconf, Cviz, DBC_tool, chassis debugging</td><td>None</td></tr><tr><td><strong>Wheel.App 2.28</strong></td><td>Localization, perception, prediction, planning, control</td><td>Calibration, time sync, dynamics calibration, CARLA bridge</td><td>None</td></tr><tr><td><strong>Wheel.App 6.30</strong></td><td>Middleware, hardware, localization, perception, prediction, planning, control</td><td>Vehicle-dynamics modeling</td><td>Functional safety, dispatch, remote driving</td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Features are prioritized incrementally for stability and performance.</li><li>Tool modules evolve with feature requirements.</li><li>Operational modules will be refined in later releases to support safety and fleet operations.</li></ul>',17)])])}const u=a(n,[["render",r]]);export{m as __pageData,u as default};
